"""Runtime of the code generated by all backends."""

from src.plots import generate_box_plot
from src.runs import Runtime

VARIANTS = ["LLVM", "Cranelift", "LLVM O1", "TPDE", "TPDE inline"]


def get_config():
    return [Runtime(VARIANTS)]


def evaluate(results):
    runs = get_config()

    generate_box_plot("runtime_compare",
                      "Runtime relative to LLVM -O0",
                      results, runs, VARIANTS)
